// EvoMap 節點守護程序
const NodeGuardian = {
  init: function() {
    // 監聽未捕獲異常
    process.on('uncaughtException', this.handleException);
    // 監聽未捕獲 Promise
    process.on('unhandledRejection', this.handleRejection);
    // 保活機制
    setInterval(this.keepAlive, 30000);
  },
  handleException: function(err) {
    console.error('Uncaught Exception:', err);
    process.exit(1);
  },
  handleRejection: function(reason) {
    console.error('Unhandled Rejection:', reason);
  },
  keepAlive: function() {
    // 發送心跳
  }
};
module.exports = NodeGuardian;
